import React from "react";
import { useNavigate } from "react-router-dom";
import "./JobList.css";

const jobs = [
  {
    id: 1,
    title: "Frontend Developer",
    role: "React.js Developer",
    location: "Bengaluru",
    experience: "2-4 years",
    skills: "React, JavaScript, HTML, CSS",
    description: "Build responsive UI components and optimize user experience.",
  },
  {
    id: 2,
    title: "Backend Engineer",
    role: "Node.js Developer",
    location: "Hyderabad",
    experience: "3-5 years",
    skills: "Node.js, Express, MongoDB",
    description: "Develop REST APIs and manage database operations.",
  },
];

export default function JobList() {
  const navigate = useNavigate();

  return (
    <div className="job-list-container">
      {jobs.map((job) => (
        <div key={job.id} className="job-card" onClick={() => navigate(`/job/${job.id}`)}>
          <h2>{job.title}</h2>
          <p><strong>Role:</strong> {job.role}</p>
          <p><strong>Location:</strong> {job.location}</p>
          <p><strong>Experience:</strong> {job.experience}</p>
          <p><strong>Skills:</strong> {job.skills}</p>
          <p className="short-desc">{job.description}</p>
        </div>
      ))}
    </div>
  );
}
